package proto

import (
	"io"
	"reflect"
	"strconv"
	"strings"
)

func parseClosedEnum(s string) map[int32]bool {
	out := make(map[int32]bool)
	for _, part := range strings.Split(s, ":") {
		n, err := strconv.ParseInt(part, 10, 32)
		if err != nil {
			panic("proto: invalid enum_closed metadata")
		}
		out[int32(n)] = true
	}
	return out
}

// Closed enum metadata is opt-in. Historical generated code keeps its original
// open-enum behavior, including proto2 code generated by v1.3.2.
type closedEnumFilter struct {
	values       map[int32]bool
	mapValue     bool
	allowPacked  bool
	strictMap    bool
	verifyMapKey bool
}

func (u *unmarshalInfo) setClosedEnum(tag int, f *reflect.StructField) {
	tags := f.Tag.Get("protobuf")
	isMap := f.Type.Kind() == reflect.Map
	if isMap {
		tags = f.Tag.Get("protobuf_val")
	}
	var p Properties
	p.Parse(tags)
	if len(p.ClosedEnum) == 0 {
		return
	}
	c := &closedEnumFilter{values: p.ClosedEnum, mapValue: isMap, allowPacked: p.Repeated, strictMap: isMap}
	if isMap {
		var key Properties
		key.Parse(f.Tag.Get("protobuf_key"))
		c.verifyMapKey = f.Type.Key().Kind() == reflect.String && key.proto3 && !key.UTF8None
	}
	if tag < len(u.dense) && u.dense[tag].unmarshal != nil {
		u.dense[tag].closed = c
	} else {
		f := u.sparse[uint64(tag)]
		f.closed = c
		u.sparse[uint64(tag)] = f
	}
}

func appendEnumVarint(b []byte, n uint64) []byte {
	for n >= 128 {
		b = append(b, byte(n)|128)
		n >>= 7
	}
	return append(b, byte(n))
}

// filter returns the input untouched on rejection so that the normal unknown
// field path retains the entire field (or map entry). Packed unknown values
// become individual unknown varints, matching the Protobuf closed-enum rules.
func (c *closedEnumFilter) filter(b []byte, wire int, tag uint64) ([]byte, []byte, error) {
	if wire == WireVarint && !c.mapValue {
		n, size := decodeVarint(b)
		if size == 0 {
			return b, nil, io.ErrUnexpectedEOF
		}
		if !c.values[int32(n)] {
			return b, nil, errInternalBadWireType
		}
		return b, nil, nil
	}
	if wire != WireBytes || (!c.mapValue && !c.allowPacked) {
		return b, nil, errInternalBadWireType
	}
	n, size := decodeVarint(b)
	if size == 0 || n > uint64(len(b)-size) {
		return b, nil, io.ErrUnexpectedEOF
	}
	body, rest := b[size:size+int(n)], b[size+int(n):]
	if c.mapValue {
		if c.strictMap {
			if err := validateEditionMap(body, c.verifyMapKey); err != nil {
				return b, nil, err
			}
		}
		valid := true
		for len(body) > 0 {
			key, k := decodeVarint(body)
			if k == 0 {
				return b, nil, io.ErrUnexpectedEOF
			}
			if err := validateWireKey(key, k); err != nil {
				return b, nil, err
			}
			body = body[k:]
			if key == 2<<3 {
				value, v := decodeVarint(body)
				if v == 0 {
					return b, nil, io.ErrUnexpectedEOF
				}
				valid = c.values[int32(value)]
			}
			var err error
			body, err = skipField(body, int(key)&7, key>>3)
			if err != nil {
				return b, nil, err
			}
		}
		if !valid {
			return b, nil, errInternalBadWireType
		}
		return b, nil, nil
	}
	var known, unknown []byte
	for len(body) > 0 {
		value, v := decodeVarint(body)
		if v == 0 {
			return b, nil, io.ErrUnexpectedEOF
		}
		if c.values[int32(value)] {
			known = append(known, body[:v]...)
		} else {
			unknown = appendEnumVarint(unknown, tag<<3)
			unknown = append(unknown, body[:v]...)
		}
		body = body[v:]
	}
	if len(unknown) == 0 {
		return b, nil, nil
	}
	filtered := appendEnumVarint(nil, uint64(len(known)))
	filtered = append(filtered, known...)
	filtered = append(filtered, rest...)
	return filtered, unknown, nil
}
